function collatz(n){
  n=Math.floor(Math.abs(+n));
  if(isNaN(n)||n<1) return {error:'请输入正整数'};
  if(n>1e7) return {error:'数值过大（上限 1e7）'};
  var seq=[n], s=n, steps=0;
  while(s!==1){ s = (s%2===0) ? s/2 : 3*s+1; seq.push(s); steps++; }
  var peak=seq.reduce(function(a,b){return b>a?b:a;}, 0);
  return {value:seq, steps:steps, peak:peak, origin:n};
}
var EXPORTS={collatz:collatz};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CollatzForgePure = EXPORTS; }
